namespace ifm4ref {
static std::vector<float>
kernel (int m, int la, int iink, int jink, int jump, int inc1, int inc2,
        const std::vector<float> &a, const std::vector<float> &ci,
        const std::vector<float> &trigs)
{
  const float sin45 = 0.7071067812f;
  std::vector<float> c = ci;
  int k = 0, ia = 1, ja = 1;
  while (k <= m/2) {
    int k_old = k;  k = k_old + la;
    int ia1 = ia, ja1 = ja;
    std::vector<float> c1 = c;
    if (k_old == 0) {
      for (int l = 1; l <= la; l++) {
        int ia1o = ia1, ja1o = ja1;
        ia1 = ia1o + inc1;  ja1 = ja1o + inc2;
        int ib = ia1o + iink, ic = ib + iink, id = ic + iink;
        int jb = ja1o + jink, jc = jb + jink;
        float a1 = a[ia1o] + a[ic], a2 = a[ib] + a[id];
        float a3 = a[ia1o] - a[ic], a4 = a[id] - a[ib];
        c1[ja1o] = a1 + a2; c1[jb] = a3; c1[jc] = a1 - a2; c1[jb+1] = a4;
      }
      ia = ia1 + jump; ja = ja1; c = c1;
    } else if (2*k_old < m) {
      int lower = jink + 2, lupper = iink*2 + jink - 2;
      for (int l = lower; l <= lupper; l += 4) {
        int ia1o = ia1, ja1o = ja1, lo = l;
        ia1 = ia1o + inc1;  ja1 = ja1o + inc2;
        int ib = ia1o + iink, ic = ib + iink, id = ic + iink;
        int jb = ja1o + jink, jdxx = lo - ja1o, jcxx = jdxx + jink;
        int kb = k_old*2, kc = kb*2, kd = kc + kb;
        float tempr1 = a[ib]*trigs[kb+1] - a[ib+1]*trigs[kb+2];
        float tempi1 = a[ib]*trigs[kb+2] + a[ib+1]*trigs[kb+1];
        float tempr2 = a[ic]*trigs[kc+1] - a[ic+1]*trigs[kc+2];
        float tempi2 = a[ic]*trigs[kc+2] + a[ic+1]*trigs[kc+1];
        float tempr3 = a[id]*trigs[kd+1] - a[id+1]*trigs[kd+2];
        float tempi3 = a[id]*trigs[kd+2] + a[id+1]*trigs[kd+1];
        float a0 = a[ia1o] + tempr2, a1 = tempr1 + tempr3;
        float a2 = a[ia1o] - tempr2, a3 = tempr1 - tempr3;
        float b0 = a[ia1o+1] + tempi2, b1 = tempi1 + tempi3;
        float b2 = a[ia1o+1] - tempi2, b3 = tempi1 - tempi3;
        c1[ja1o]   = a0 + a1; c1[jb]     = a2 + b3;
        c1[jcxx]   = a0 - a1; c1[jdxx]   = a2 - b3;
        c1[ja1o+1] = b0 + b1; c1[jb+1]   = b2 - a3;
        c1[jcxx+1] = b1 - b0; c1[jdxx+1] = -b2 - a3;
      }
      ia = ia1 + jump; ja = ja1; c = c1;
    } else {
      for (int l = 1; l <= la; l++) {
        int ia1o = ia1, ja1o = ja1;
        ia1 = ia1o + inc1;  ja1 = ja1o + inc2;
        int ib = ia1o + iink, ic = ib + iink, id = ic + iink;
        int jb = ja1o + jink;
        float a1 = sin45 * (a[ib] - a[id]);
        float a2 = sin45 * (a[ib] + a[id]);
        c1[ja1o]   = a[ia1o] + a1;  c1[jb]   = a[ia1o] - a1;
        c1[ja1o+1] = -a[ic] - a2;   c1[jb+1] = a[ic] - a2;
      }
      ia = ia1; ja = ja1; c = c1;
    }
  }
  return c;
}
}
