  using namespace bmb;
  const int nx = 8, ny = 8, nx2 = nx + 2, ngrid = nx2 * (ny + 2), np = 6;
  const double xmax = 1.0, hxi = (double)nx / xmax, hyi = (double)ny / xmax;
  const double qmult = -1.0, wmult = 1.0;
