#ifdef TEST_UNSPLIT_UPDATE_DV
// unsplit, part 7c of 8 -- Method17..Method19 and Transpose, the update tail.
//
// CONSERVATION is the headline, and the sharpest check anywhere in this port.
// Method19 updates each cell by a FLUX DIFFERENCE, so summing over the interior
// TELESCOPES -- sum_i (F[j,i] - F[j,i+1]) = F[j,1] - F[j,nc1+1] -- everything
// interior cancels and only the domain-edge fluxes survive.  With matching edge
// fluxes the total of each conserved quantity is unchanged EXACTLY, not to a
// tolerance.  A sign error, a transposed index or an off-by-one in the flux
// subscripts all break the cancellation.
namespace uup {
  const int NCX = 4;
  struct P {                     // wide plane over 1-NCX .. n+NCX (+pad for ilo)
    int nc1, nc2, pad, W_, H_;
    std::vector<double> a;
    P (int c1, int c2, int pd, double f)
        : nc1 (c1), nc2 (c2), pad (pd), W_ (c1 + 2 * NCX + pd),
          H_ (c2 + 2 * NCX), a ((size_t)W_ * H_, f) {}
    double &at (int j, int i) { return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))]; }
    double at (int j, int i) const { return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))]; }
    sisal_array_t dope () const {
      sisal_array_t d = sisal_array_alloc_sized (2, 4, (uint64_t)a.size (), sizeof (double));
      d.dims[0] = H_; d.dims[1] = W_;
      d.lower_bound[0] = 1 - NCX; d.lower_bound[1] = 1 - NCX;
      memcpy (d.data, a.data (), a.size () * sizeof (double));
      return d;
    }
  };
  // Method17/18A/18B/19 transcribed.  The property checks (conservation, zero
  // and uniform fluxes, expanding vs compressing) all hold for whole families
  // of wrong coefficients, so the general case is checked against the formula
  // too, with a compressing flow so the viscosity term is live.
  struct Ref {
    std::vector<double> div, g1, g2, w;
  };
  static void ref_update (const P &U, const P &velx, const P &vely, const P &f1,
                          const P &f2, int nc1, int nc2, int ilo, double difmag,
                          double dx, double dy, double dtdx, double dtdy,
                          Ref &out, int *n_compress, int *n_expand)
  {
    // Method17: divergence over je in 1..nc2+1, ie in 1..nc1+1
    const int DW = nc1 + 1;
    out.div.assign ((size_t)DW * (nc2 + 1), 0.0);
    for (int je = 1; je <= nc2 + 1; je++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          double ud = velx.at (je, ie) - velx.at (je, ie - 1)
                      + velx.at (je - 1, ie) - velx.at (je - 1, ie - 1);
          double vd = vely.at (je, ie) - vely.at (je, ie - 1)
                      + vely.at (je - 1, ie) - vely.at (je - 1, ie - 1);
          out.div[(size_t)(je - 1) * DW + (ie - 1)]
              = difmag * 0.5 * (ud / dx + vd / dy);
        }
    auto D = [&] (int j, int i) {
      return out.div[(size_t)(j - 1) * DW + (i - 1)];
    };
    // Method18A: x fluxes over jc in 1..nc2, ie in 1..nc1+1
    out.g1.assign ((size_t)DW * nc2, 0.0);
    for (int jc = 1; jc <= nc2; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          double d1 = std::min (0.0, 0.5 * (D (jc, ie) + D (jc + 1, ie)));
          if (d1 < 0.0) { if (n_compress) (*n_compress)++; }
          else if (n_expand) (*n_expand)++;
          out.g1[(size_t)(jc - 1) * DW + (ie - 1)]
              = f1.at (jc, ie)
                + dx * d1 * (U.at (jc, ilo + ie - 1) - U.at (jc, ilo + ie - 2));
        }
    // Method18B: y fluxes over je in 1..nc2+1, ic in 1..nc1
    const int GW = nc1;
    out.g2.assign ((size_t)GW * (nc2 + 1), 0.0);
    for (int je = 1; je <= nc2 + 1; je++)
      for (int ic = 1; ic <= nc1; ic++)
        {
          double d2 = std::min (0.0, 0.5 * (D (je, ic) + D (je, ic + 1)));
          out.g2[(size_t)(je - 1) * GW + (ic - 1)]
              = f2.at (je, ic)
                + dy * d2 * (U.at (je, ilo + ic - 1) - U.at (je - 1, ilo + ic - 1));
        }
    // Method19: the conservative update over 1..nc2 x 1..nc1
    out.w.assign ((size_t)nc1 * nc2, 0.0);
    for (int j = 1; j <= nc2; j++)
      for (int i = 1; i <= nc1; i++)
        out.w[(size_t)(j - 1) * nc1 + (i - 1)]
            = U.at (j, ilo + i - 1)
              + dtdx * (out.g1[(size_t)(j - 1) * DW + (i - 1)]
                        - out.g1[(size_t)(j - 1) * DW + i])
              + dtdy * (out.g2[(size_t)(j - 1) * GW + (i - 1)]
                        - out.g2[(size_t)j * GW + (i - 1)]);
  }
}
static void test_unsplit_update_dv (void)
{
  printf ("\n=== Group: unsplit_update_dv (part 7c/8: divergence, viscosity, "
          "conservative update) ===\n");
  using namespace uup;
  const int nc1 = 6, nc2 = 5, ilo = 1, pad = 2;
  const double dx = 0.25, dy = 0.5, dtdx = 0.1, dtdy = 0.2;

  auto freer = [] (FUNC_MAIN_uup_results &r) {
    sisal_array_t *v[] = { &r.div, &r.g1a, &r.g1b, &r.g1c, &r.g1d, &r.g2a,
                           &r.g2b, &r.g2c, &r.g2d, &r.w1, &r.w2, &r.w3, &r.w4,
                           &r.t1, &r.t2, &r.t3, &r.t4 };
    for (auto *x : v) if (x->data) free (x->data);
  };
  auto call = [&] (P &U1, P &U2, P &U3, P &U4, P &u1, P &v1,
                   P &f1a, P &f1b, P &f1c, P &f1d,
                   P &f2a, P &f2b, P &f2c, P &f2d, double difmag) {
    sisal_array_t A[14] = { U1.dope (), U2.dope (), U3.dope (), U4.dope (),
                            u1.dope (), v1.dope (), f1a.dope (), f1b.dope (),
                            f1c.dope (), f1d.dope (), f2a.dope (), f2b.dope (),
                            f2c.dope (), f2d.dope () };
    auto r = func_MAIN (A[0], A[1], A[2], A[3], A[4], A[5], A[6], A[7], A[8],
                        A[9], A[10], A[11], A[12], A[13], nc1, nc2, ilo,
                        difmag, dx, dy, dtdx, dtdy);
    for (auto &x : A) if (x.data) free (x.data);
    return r;
  };

  // the updated state spans 1..nc2 x 1..nc1
  auto wat = [&] (const sisal_array_t &a, int j, int i) {
    return ((const double *)a.data)[(size_t)(j - 1) * nc1 + (i - 1)];
  };

  // ---- CONSERVATION: periodic edge fluxes leave the totals untouched ----
  {
    P U1 (nc1, nc2, pad, 0), U2 (nc1, nc2, pad, 0), U3 (nc1, nc2, pad, 0),
        U4 (nc1, nc2, pad, 0), u1 (nc1, nc2, pad, 0), v1 (nc1, nc2, pad, 0);
    P f1a (nc1, nc2, pad, 0), f1b (nc1, nc2, pad, 0), f1c (nc1, nc2, pad, 0),
        f1d (nc1, nc2, pad, 0), f2a (nc1, nc2, pad, 0), f2b (nc1, nc2, pad, 0),
        f2c (nc1, nc2, pad, 0), f2d (nc1, nc2, pad, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
        {
          U1.at (j, i) = 1.0 + 0.125 * ((i + j) % 5);
          U2.at (j, i) = 0.25 * ((i * 3 + j) % 4);
          U3.at (j, i) = 0.125 * ((i + j * 2) % 3);
          U4.at (j, i) = 2.0 + 0.0625 * ((i + 2 * j) % 7);
        }
    // fluxes PERIODIC in each direction, so F[j,1] == F[j,nc1+1] exactly
    auto fill_per = [&] (P &F, double amp) {
      for (int j = 1 - NCX; j <= nc2 + NCX; j++)
        for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
          {
            int ii = ((i - 1) % nc1 + nc1) % nc1;       // period nc1 in i
            int jj = ((j - 1) % nc2 + nc2) % nc2;
            F.at (j, i) = amp * (0.125 * ii + 0.0625 * jj);
          }
    };
    fill_per (f1a, 1.0); fill_per (f1b, 2.0); fill_per (f1c, 0.5);
    fill_per (f1d, 1.5); fill_per (f2a, 1.0); fill_per (f2b, 2.0);
    fill_per (f2c, 0.5); fill_per (f2d, 1.5);

    // difmag = 0 turns the viscosity off, so the update is the pure flux
    // difference and the telescoping is exact
    auto r = call (U1, U2, U3, U4, u1, v1, f1a, f1b, f1c, f1d,
                   f2a, f2b, f2c, f2d, 0.0);

    const sisal_array_t *outs[4] = { &r.w1, &r.w2, &r.w3, &r.w4 };
    const P *ins[4] = { &U1, &U2, &U3, &U4 };
    bool ok = true;
    for (int q = 0; q < 4; q++)
      {
        double before = 0, after = 0;
        for (int j = 1; j <= nc2; j++)
          for (int i = 1; i <= nc1; i++)
            { before += ins[q]->at (j, ilo + i - 1); after += wat (*outs[q], j, i); }
        if (fabs (after - before) > 1e-12 * std::max (1.0, fabs (before)))
          { printf ("  quantity %d: total %.17g -> %.17g\n", q, before, after);
            ok = false; }
      }
    check ("CONSERVATION: periodic edge fluxes leave every total unchanged", ok);
    freer (r);
  }

  // ---- zero and uniform fluxes leave the state untouched ----
  {
    P U1 (nc1, nc2, pad, 0), U2 (nc1, nc2, pad, 0), U3 (nc1, nc2, pad, 0),
        U4 (nc1, nc2, pad, 0), u1 (nc1, nc2, pad, 0), v1 (nc1, nc2, pad, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
        { U1.at (j, i) = 1.0 + 0.5 * ((i * j) % 3); U2.at (j, i) = 0.25 * i;
          U3.at (j, i) = 0.5; U4.at (j, i) = 3.0; }
    for (double flat : { 0.0, 2.75 })
      {
        P f (nc1, nc2, pad, flat);
        auto r = call (U1, U2, U3, U4, u1, v1, f, f, f, f, f, f, f, f, 0.0);
        bool ok = true;
        for (int j = 1; ok && j <= nc2; j++)
          for (int i = 1; i <= nc1; i++)
            if (wat (r.w1, j, i) != U1.at (j, ilo + i - 1)) { ok = false; break; }
        char m[120];
        snprintf (m, sizeof m,
                  "%s flux leaves the state bit-for-bit unchanged",
                  flat == 0.0 ? "zero" : "uniform");
        check (m, ok);
        freer (r);
      }
  }

  // ---- Method17: uniform velocity has exactly zero divergence ----
  {
    P U1 (nc1, nc2, pad, 1.0), U2 (nc1, nc2, pad, 0), U3 (nc1, nc2, pad, 0),
        U4 (nc1, nc2, pad, 1.0), f (nc1, nc2, pad, 0);
    P uu (nc1, nc2, pad, 0.75), vv (nc1, nc2, pad, -0.25);   // uniform
    auto r = call (U1, U2, U3, U4, uu, vv, f, f, f, f, f, f, f, f, 1.0);
    bool ok = true;
    for (int k = 0; k < (int)r.div.size; k++)
      if (((const double *)r.div.data)[k] != 0.0) ok = false;
    check ("Method17: a uniform velocity field has exactly zero divergence", ok);
    freer (r);
  }

  // ---- Method18 acts only where the flow COMPRESSES ----
  {
    P U1 (nc1, nc2, pad, 0), U2 (nc1, nc2, pad, 0), U3 (nc1, nc2, pad, 0),
        U4 (nc1, nc2, pad, 0), f (nc1, nc2, pad, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
        { U1.at (j, i) = 1.0 + 0.25 * i; U2.at (j, i) = 0.5 * i;
          U3.at (j, i) = 0.25 * j; U4.at (j, i) = 2.0 + 0.125 * i;
          f.at (j, i) = 0.5 + 0.125 * ((i + j) % 3); }
    P uexp (nc1, nc2, pad, 0), vexp (nc1, nc2, pad, 0);
    P ucmp (nc1, nc2, pad, 0), vcmp (nc1, nc2, pad, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
        { uexp.at (j, i) =  0.5 * i; vexp.at (j, i) =  0.5 * j;    // diverging
          ucmp.at (j, i) = -0.5 * i; vcmp.at (j, i) = -0.5 * j; }  // converging

    auto re = call (U1, U2, U3, U4, uexp, vexp, f, f, f, f, f, f, f, f, 1.0);
    auto rc = call (U1, U2, U3, U4, ucmp, vcmp, f, f, f, f, f, f, f, f, 1.0);
    // expanding: min(0, div) is 0, so the flux comes through untouched
    bool same = true;
    for (int k = 0; k < (int)re.g1a.size; k++)
      if (((const double *)re.g1a.data)[k] != ((const double *)f.dope ().data)[0]
          && false) same = same;                        // (compared below)
    // compare against the uncorrected flux directly
    int changed_e = 0, changed_c = 0;
    for (int jc = 1; jc <= nc2; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          double base = f.at (jc, ie);
          double ge = ((const double *)re.g1a.data)[(size_t)(jc - 1) * (nc1 + 1) + (ie - 1)];
          double gc = ((const double *)rc.g1a.data)[(size_t)(jc - 1) * (nc1 + 1) + (ie - 1)];
          if (ge != base) changed_e++;
          if (gc != base) changed_c++;
        }
    check ("Method18: an EXPANDING flow leaves the fluxes untouched",
           changed_e == 0);
    check ("Method18: a COMPRESSING flow does alter them", changed_c > 0);
    (void)same;
    freer (re); freer (rc);
  }

  // ---- GENERAL CASE against the transcribed formulas ----
  {
    P U1 (nc1, nc2, pad, 0), U2 (nc1, nc2, pad, 0), U3 (nc1, nc2, pad, 0),
        U4 (nc1, nc2, pad, 0), uu (nc1, nc2, pad, 0), vv (nc1, nc2, pad, 0),
        F1 (nc1, nc2, pad, 0), F2 (nc1, nc2, pad, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
        {
          U1.at (j, i) = 1.0 + 0.125 * ((i * 3 + j) % 5);
          U2.at (j, i) = 0.25 * ((i + 2 * j) % 4) - 0.5;
          U3.at (j, i) = 0.125 * ((i + j) % 3);
          U4.at (j, i) = 2.0 + 0.0625 * ((i * j) % 7);
          // V-shaped, so the divergence changes SIGN across the domain: a
          // monotone velocity ramp compresses everywhere and leaves the
          // min(0, div) branch half-untested (measured: 35 compressing cells,
          // 0 expanding).
          uu.at (j, i) = fabs ((double)(i - 3)) - 0.3 * j;
          vv.at (j, i) = fabs ((double)(j - 2)) - 0.2 * i;
          F1.at (j, i) = 0.5 + 0.125 * ((i + j) % 3);
          F2.at (j, i) = 0.25 - 0.0625 * ((i * 2 + j) % 4);
        }
    const double difmag = 0.75;
    auto r = call (U1, U2, U3, U4, uu, vv, F1, F1, F1, F1, F2, F2, F2, F2,
                   difmag);
    int ncomp = 0, nexp = 0;
    Ref ref;
    ref_update (U1, uu, vv, F1, F2, nc1, nc2, ilo, difmag, dx, dy, dtdx, dtdy,
                ref, &ncomp, &nexp);
    bool okd = (int)r.div.size == (int)ref.div.size();
    for (size_t k = 0; okd && k < ref.div.size(); k++)
      if (fabs (((const double *)r.div.data)[k] - ref.div[k]) > 1e-12) okd = false;
    check ("general case: Method17 divergence matches the formula", okd);
    bool okg = (int)r.g1a.size == (int)ref.g1.size();
    for (size_t k = 0; okg && k < ref.g1.size(); k++)
      if (fabs (((const double *)r.g1a.data)[k] - ref.g1[k]) > 1e-12) okg = false;
    check ("general case: Method18A viscous x-flux matches the formula", okg);
    bool okw = (int)r.w1.size == (int)ref.w.size();
    for (size_t k = 0; okw && k < ref.w.size(); k++)
      if (fabs (((const double *)r.w1.data)[k] - ref.w[k]) > 1e-12) okw = false;
    check ("general case: Method19 update matches the formula", okw);
    char m[150];
    snprintf (m, sizeof m,
              "...with the viscosity live on both sides (%d compressing, %d "
              "expanding cells)", ncomp, nexp);
    check (m, ncomp > 0 && nexp > 0);
    freer (r);
  }

  // ---- Transpose is exactly invertible ----
  {
    P U1 (nc1, nc2, pad, 1.0), U2 (nc1, nc2, pad, 0), U3 (nc1, nc2, pad, 0),
        U4 (nc1, nc2, pad, 1.0), uu (nc1, nc2, pad, 0), vv (nc1, nc2, pad, 0);
    P f (nc1, nc2, pad, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX + pad; i++)
        f.at (j, i) = 100.0 * j + i;                 // every cell distinct
    auto r = call (U1, U2, U3, U4, uu, vv, f, f, f, f, f, f, f, f, 0.0);
    // Transpose( g1a, 1..nc2 outer, 1..nc1+1 inner ) reads [ic,je]
    bool ok = r.t1.rank == 2 && (int)r.t1.dims[0] == nc2
              && (int)r.t1.dims[1] == nc1 + 1;
    for (int je = 1; ok && je <= nc2; je++)
      for (int ic = 1; ic <= nc1 + 1; ic++)
        {
          double t = ((const double *)r.t1.data)[(size_t)(je - 1) * (nc1 + 1) + (ic - 1)];
          double src = ((const double *)r.g1a.data)[(size_t)(ic - 1) * (nc1 + 1) + (je - 1)];
          if (t != src) { ok = false; break; }
        }
    check ("Transpose reads [ic,je] -- the axes really are swapped", ok);
    freer (r);
  }
}
#endif
#ifdef TEST_UNSPLIT_TRACE_DV
// unsplit, part 7b of 8 -- Method5..Method8, the traced (predicted) states.
//
// Each takes the cell state plus the LIMITED SLOPES from part 4 and predicts
// the interface state half a step ahead, keeping only the characteristic
// families travelling toward that interface (the `if uu >= zero` guards).
// First part to CONSUME a rank-3: slopes arrive as drho[1,..] for x and
// drho[2,..] for y, exactly the two-plane result part 4 produces.
//
// Properties: with ZERO slopes every traced state must equal its cell state
// (the predictor's analogue of part 6's consistency); at dtdx = 0 the left and
// right states must STRADDLE the cell value by half a slope, separating the
// spatial reconstruction from the characteristic terms; and reversing the flow
// must change the answer, since the beta terms are gated on the velocity sign.
namespace utr {
  const int NCX = 4;
  struct P {                        // wide rank-2 plane, 1-NCX .. n+NCX
    int nc1, nc2, W_, H_;
    std::vector<double> a;
    P (int c1, int c2, double f)
        : nc1 (c1), nc2 (c2), W_ (c1 + 2 * NCX), H_ (c2 + 2 * NCX),
          a ((size_t)W_ * H_, f) {}
    double &at (int j, int i) { return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))]; }
    double at (int j, int i) const { return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))]; }
    sisal_array_t dope () const {
      sisal_array_t d = sisal_array_alloc_sized (2, 4, (uint64_t)a.size (), sizeof (double));
      d.dims[0] = H_; d.dims[1] = W_;
      d.lower_bound[0] = 1 - NCX; d.lower_bound[1] = 1 - NCX;
      memcpy (d.data, a.data (), a.size () * sizeof (double));
      return d;
    }
  };
  struct S {                        // rank-3 slopes (2, ny, nx) over 1-NCX..n+NCX
    int nc1, nc2, W_, H_;
    std::vector<double> a;
    S (int c1, int c2, double f)
        : nc1 (c1), nc2 (c2), W_ (c1 + 2 * NCX), H_ (c2 + 2 * NCX),
          a ((size_t)2 * W_ * H_, f) {}
    double &at (int k, int j, int i) {
      return a[((size_t)(k - 1) * H_ + (j - (1 - NCX))) * W_ + (i - (1 - NCX))];
    }
    double at (int k, int j, int i) const {
      return a[((size_t)(k - 1) * H_ + (j - (1 - NCX))) * W_ + (i - (1 - NCX))];
    }
    sisal_array_t dope () const {
      sisal_array_t d = sisal_array_alloc_sized (3, 4, (uint64_t)a.size (), sizeof (double));
      d.dims[0] = 2; d.dims[1] = H_; d.dims[2] = W_;
      d.lower_bound[0] = 1; d.lower_bound[1] = 1 - NCX; d.lower_bound[2] = 1 - NCX;
      memcpy (d.data, a.data (), a.size () * sizeof (double));
      return d;
    }
  };
  // The formula for Method5 (traced LEFT states), transcribed.  The property
  // checks above all use DEGENERATE configurations -- zero slopes, or dt = 0 --
  // so a wrong coefficient that vanishes in both would survive them.  This runs
  // the general case: non-zero dt AND non-zero slopes.
  static void ref_method5 (const P &c, const P &u, const P &v, const P &rho,
                           const P &p, const P &psml, const S &drho,
                           const S &dp, const S &du, const S &dv, int nc1,
                           int nc2, double dtdx, double hdtdx, double smallr,
                           std::vector<double> &rl, std::vector<double> &ul_,
                           std::vector<double> &vl_, std::vector<double> &pl_)
  {
    const int W = nc1 + 1;
    rl.assign ((size_t)W * (nc2 + 2), 0.0);
    ul_ = vl_ = pl_ = rl;
    for (int jc = 0; jc <= nc2 + 1; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          const int ic = ie - 1;
          const double cc = c.at (jc, ic), uu = u.at (jc, ic);
          const double alpha = 0.5 * (1.0 - dtdx * std::max (0.0, uu + cc));
          const double t2 = cc * drho.at (1, jc, ic) - dp.at (1, jc, ic) / cc;
          const double beta0 = (uu >= 0.0) ? t2 : 0.0;
          const double t3 = 2.0 * (dp.at (1, jc, ic) / rho.at (jc, ic)
                                   - cc * du.at (1, jc, ic));
          const double betam = (uu - cc >= 0.0) ? t3 : 0.0;
          const double beta = (uu >= 0.0) ? cc * dv.at (1, jc, ic) : 0.0;
          const size_t k = (size_t)jc * W + (ie - 1);
          double r2 = rho.at (jc, ic) + alpha * drho.at (1, jc, ic)
                      + hdtdx * (beta0 + 0.5 * rho.at (jc, ic) * betam / cc);
          rl[k]  = std::max (smallr, r2);
          ul_[k] = u.at (jc, ic) + alpha * du.at (1, jc, ic) - hdtdx * 0.5 * betam;
          vl_[k] = v.at (jc, ic) + alpha * dv.at (1, jc, ic) + hdtdx * beta;
          double p2 = p.at (jc, ic) + alpha * dp.at (1, jc, ic)
                      + hdtdx * 0.5 * rho.at (jc, ic) * cc * betam;
          pl_[k] = std::max (psml.at (jc, ic),
                             std::max (psml.at (jc, ic + 1), p2));
        }
  }
}
static void test_unsplit_trace_dv (void)
{
  printf ("\n=== Group: unsplit_trace_dv (part 7b/8: Method5..8) ===\n");
  using namespace utr;
  const int nc1 = 5, nc2 = 4;
  const double smallr = 1e-10;

  // a physical background state; velocities are given per-cell so the flow can
  // be reversed wholesale
  auto make = [&] (double usign, double slope_scale) {
    P c (nc1, nc2, 0), u (nc1, nc2, 0), v (nc1, nc2, 0), rho (nc1, nc2, 0),
        p (nc1, nc2, 0), psml (nc1, nc2, 0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        {
          rho.at (j, i) = 1.0 + 0.125 * ((i + 5) % 4);
          p.at (j, i)   = 1.0 + 0.25 * ((j + 3) % 3);
          // Velocities must span SUBSONIC and SUPERSONIC, both signs.  The
          // characteristic guards are `uu >= 0` and `uu - cc >= 0` with
          // cc = sqrt(1.4 p / rho) ~ 1.2 here, so an all-subsonic field (the
          // first version of this test) left betam identically zero and the
          // whole acoustic term untested -- a perturbation of its coefficient
          // passed.  The coverage assertion below stops that returning.
          u.at (j, i)   = usign * (2.0 * ((i + 1) % 5) - 3.0);
          v.at (j, i)   = usign * (0.25 + 0.125 * ((j + 2) % 3));
          c.at (j, i)   = sqrt (1.4 * p.at (j, i) / rho.at (j, i));
          psml.at (j, i) = 1e-8;
        }
    S drho (nc1, nc2, 0), dp (nc1, nc2, 0), du (nc1, nc2, 0), dv (nc1, nc2, 0);
    for (int k = 1; k <= 2; k++)
      for (int j = 1 - NCX; j <= nc2 + NCX; j++)
        for (int i = 1 - NCX; i <= nc1 + NCX; i++)
          {
            drho.at (k, j, i) = slope_scale * 0.0625 * ((i + j + k) % 3 - 1);
            dp.at (k, j, i)   = slope_scale * 0.125  * ((i + 2 * j) % 3 - 1);
            du.at (k, j, i)   = slope_scale * 0.03125 * ((i * k + j) % 3 - 1);
            dv.at (k, j, i)   = slope_scale * 0.03125 * ((i + j * k) % 3 - 1);
          }
    return std::make_tuple (c, u, v, rho, p, psml, drho, dp, du, dv);
  };

  auto call = [&] (auto &t, double dtdx, double dtdy) {
    auto &[c, u, v, rho, p, psml, drho, dp, du, dv] = t;
    sisal_array_t A[10] = { c.dope (), u.dope (), v.dope (), rho.dope (),
                            p.dope (), psml.dope (), drho.dope (), dp.dope (),
                            du.dope (), dv.dope () };
    auto r = func_MAIN (A[0], A[1], A[2], A[3], A[4], A[5], A[6], A[7], A[8],
                        A[9], nc1, nc2, dtdx, 0.5 * dtdx, dtdy, 0.5 * dtdy,
                        smallr);
    for (auto &x : A) if (x.data) free (x.data);
    return r;
  };
  auto freer = [] (FUNC_MAIN_utr_results &r) {
    sisal_array_t *v[] = { &r.rl, &r.ul, &r.vl, &r.pl, &r.rr, &r.ur, &r.vr,
                           &r.pr, &r.rb, &r.ub, &r.vb, &r.pb, &r.rt, &r.ut,
                           &r.vt, &r.pt };
    for (auto *x : v) if (x->data) free (x->data);
  };

  // x-interface results span jc in 0..nc2+1, ie in 1..nc1+1
  const int XW = nc1 + 1, XH = nc2 + 2;
  auto xat = [&] (const sisal_array_t &a, int jc, int ie) {
    return ((const double *)a.data)[(size_t)(jc - 0) * XW + (ie - 1)];
  };
  // y-interface results span je in 1..nc2+1, ic in 0..nc1+1
  const int YW = nc1 + 2;
  auto yat = [&] (const sisal_array_t &a, int je, int ic) {
    return ((const double *)a.data)[(size_t)(je - 1) * YW + (ic - 0)];
  };

  // ---- CONSISTENCY: zero slopes reproduce the cell state ----
  {
    auto t = make (1.0, 0.0);                 // slopes all zero
    auto &[c, u, v, rho, p, psml, drho, dp, du, dv] = t;
    auto r = call (t, 0.3, 0.25);
    bool ok = true;
    for (int jc = 0; ok && jc <= nc2 + 1; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          int icL = ie - 1, icR = ie;
          if (fabs (xat (r.rl, jc, ie) - rho.at (jc, icL)) > 1e-13
              || fabs (xat (r.ul, jc, ie) - u.at (jc, icL)) > 1e-13
              || fabs (xat (r.pl, jc, ie) - p.at (jc, icL)) > 1e-13
              || fabs (xat (r.rr, jc, ie) - rho.at (jc, icR)) > 1e-13
              || fabs (xat (r.pr, jc, ie) - p.at (jc, icR)) > 1e-13)
            { ok = false; break; }
        }
    check ("zero slopes: traced x-states equal their cell states exactly", ok);
    bool oky = true;
    for (int je = 1; oky && je <= nc2 + 1; je++)
      for (int ic = 0; ic <= nc1 + 1; ic++)
        {
          int jcB = je - 1, jcT = je;
          if (fabs (yat (r.rb, je, ic) - rho.at (jcB, ic)) > 1e-13
              || fabs (yat (r.vb, je, ic) - v.at (jcB, ic)) > 1e-13
              || fabs (yat (r.rt, je, ic) - rho.at (jcT, ic)) > 1e-13)
            { oky = false; break; }
        }
    check ("zero slopes: traced y-states equal their cell states exactly", oky);
    freer (r);
  }

  // ---- PURE RECONSTRUCTION at dtdx = 0: the states straddle the cell ----
  {
    auto t = make (1.0, 1.0);
    auto &[c, u, v, rho, p, psml, drho, dp, du, dv] = t;
    auto r = call (t, 0.0, 0.0);
    bool ok = true;
    for (int jc = 0; ok && jc <= nc2 + 1; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          int icL = ie - 1, icR = ie;
          double wl = rho.at (jc, icL) + 0.5 * drho.at (1, jc, icL);
          double wr = rho.at (jc, icR) - 0.5 * drho.at (1, jc, icR);
          if (fabs (xat (r.rl, jc, ie) - wl) > 1e-13
              || fabs (xat (r.rr, jc, ie) - wr) > 1e-13)
            { ok = false; break; }
        }
    check ("dt = 0: left/right states straddle the cell by half a slope", ok);
    bool oky = true;
    for (int je = 1; oky && je <= nc2 + 1; je++)
      for (int ic = 0; ic <= nc1 + 1; ic++)
        {
          double wb = rho.at (je - 1, ic) + 0.5 * drho.at (2, je - 1, ic);
          double wt = rho.at (je, ic) - 0.5 * drho.at (2, je, ic);
          if (fabs (yat (r.rb, je, ic) - wb) > 1e-13
              || fabs (yat (r.rt, je, ic) - wt) > 1e-13)
            { oky = false; break; }
        }
    check ("dt = 0: bottom/top states straddle it using the SECOND slope plane",
           oky);
    freer (r);
  }

  // ---- GENERAL CASE against the transcribed formula ----
  {
    auto t = make (1.0, 1.0);
    auto &[c, u, v, rho, p, psml, drho, dp, du, dv] = t;
    const double dtdx = 0.4, hdtdx = 0.2;
    auto r = call (t, dtdx, 0.35);
    std::vector<double> wr, wu, wv, wp;
    ref_method5 (c, u, v, rho, p, psml, drho, dp, du, dv, nc1, nc2, dtdx,
                 hdtdx, smallr, wr, wu, wv, wp);
    bool ok = true;
    for (int jc = 0; ok && jc <= nc2 + 1; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          size_t k = (size_t)jc * (nc1 + 1) + (ie - 1);
          if (fabs (xat (r.rl, jc, ie) - wr[k]) > 1e-12
              || fabs (xat (r.ul, jc, ie) - wu[k]) > 1e-12
              || fabs (xat (r.vl, jc, ie) - wv[k]) > 1e-12
              || fabs (xat (r.pl, jc, ie) - wp[k]) > 1e-12)
            { ok = false; break; }
        }
    check ("general case (dt and slopes both non-zero): traced left states "
           "match the transcribed formula", ok);

    // COVERAGE: the acoustic term is gated on uu - cc >= 0, so confirm the
    // data actually reaches both sides of every guard -- otherwise the
    // reference above is checking a formula whose branches never run.
    int n_betam = 0, n_beta0 = 0, n_zero = 0;
    for (int jc = 0; jc <= nc2 + 1; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        {
          const int ic = ie - 1;
          double cc = c.at (jc, ic), uu = u.at (jc, ic);
          if (uu - cc >= 0.0) n_betam++;
          if (uu >= 0.0) n_beta0++; else n_zero++;
        }
    char m[170];
    snprintf (m, sizeof m,
              "...and the data exercises both sides of both guards "
              "(supersonic %d, forward %d, backward %d)",
              n_betam, n_beta0, n_zero);
    check (m, n_betam > 0 && n_beta0 > 0 && n_zero > 0);
    freer (r);
  }

  // ---- UPWIND SWITCHING: reversing the flow changes the answer ----
  {
    auto tf = make (1.0, 1.0);
    auto tb = make (-1.0, 1.0);
    auto rf = call (tf, 0.4, 0.35);
    auto rb2 = call (tb, 0.4, 0.35);
    int diff = 0;
    for (int jc = 0; jc <= nc2 + 1; jc++)
      for (int ie = 1; ie <= nc1 + 1; ie++)
        if (xat (rf.rl, jc, ie) != xat (rb2.rl, jc, ie)) diff++;
    check ("reversing the flow changes the traced states (upwind switching)",
           diff > 0);
    freer (rf); freer (rb2);
  }
}
#endif
#ifdef TEST_UNSPLIT_PREP_DV
// unsplit, part 7a of 8 -- Method1..Method4, the predictor's preparation.
//
// Method1..19 plus Transpose are ~800 lines, so part 7 splits along the
// integrator's own phases: 7a prep, 7b traced states + transverse predictor,
// 7c full fluxes + divergence + update + Transpose.
//
// Property-first oracle: Method1 is a change of variables so it must INVERT
// (rho*u recovers the momentum); Method2 at rest reduces to p = gm1*rho*e and
// with negative internal energy must return its FLOOR rather than a negative
// pressure; Method3 must invert (c*c*rho/gamma recovers p); and Method4 must
// IGNORE THE GHOST CELLS -- its generator runs 1..nc, so a spike planted
// outside must not move it while the same spike inside must.
namespace upp {
  struct W {   // wide plane over 1-NCX .. n+NCX (+pad columns for the ilo shift)
    int nc1, nc2, ncx, pad, W_, H_;
    std::vector<double> a;
    W (int c1, int c2, int cx, int pd, double fill)
        : nc1 (c1), nc2 (c2), ncx (cx), pad (pd),
          W_ (c1 + 2 * cx + pd), H_ (c2 + 2 * cx),
          a ((size_t)W_ * H_, fill) {}
    double &at (int j, int i) { return a[(size_t)(j - (1 - ncx)) * W_ + (i - (1 - ncx))]; }
    double at (int j, int i) const { return a[(size_t)(j - (1 - ncx)) * W_ + (i - (1 - ncx))]; }
    sisal_array_t dope () const {
      sisal_array_t d = sisal_array_alloc_sized (2, 4, (uint64_t)a.size (), sizeof (double));
      d.dims[0] = H_; d.dims[1] = W_;
      d.lower_bound[0] = 1 - ncx; d.lower_bound[1] = 1 - ncx;
      memcpy (d.data, a.data (), a.size () * sizeof (double));
      return d;
    }
  };
}
static void test_unsplit_prep_dv (void)
{
  printf ("\n=== Group: unsplit_prep_dv (part 7a/8: Method1..4) ===\n");
  using namespace upp;
  const int nc1 = 5, nc2 = 4, ncx = 4, pad = 3;
  const double gamma = 1.4, half = 0.5, small = 1e-6, gm1 = gamma - 1.0;
  char msg[190];

  auto build = [&] (int ilo, bool rest, bool negative_eint,
                    double spike_in, double spike_out) {
    W U1 (nc1, nc2, ncx, pad, 0), U2 (nc1, nc2, ncx, pad, 0),
        U3 (nc1, nc2, ncx, pad, 0), U4 (nc1, nc2, ncx, pad, 0);
    for (int j = 1 - ncx; j <= nc2 + ncx; j++)
      for (int i = 1 - ncx; i <= nc1 + ncx + pad; i++)
        {
          double rho = 1.0 + 0.125 * ((i + 7) % 5) + 0.25 * ((j + 3) % 3);
          double u = rest ? 0.0 : 0.5 - 0.25 * ((i + 2) % 4);
          double v = rest ? 0.0 : 0.375 * ((j + 1) % 3) - 0.25;
          double eint = negative_eint ? -1.0 : 2.0 + 0.5 * ((i + j) % 3);
          double e = eint + 0.5 * (u * u + v * v);
          U1.at (j, i) = rho;
          U2.at (j, i) = rho * u;
          U3.at (j, i) = rho * v;
          U4.at (j, i) = rho * e;
        }
    // optional spikes, to probe Method4's range
    if (spike_in != 0.0)  { U2.at (2, 2) = U1.at (2, 2) * spike_in; }
    if (spike_out != 0.0) { U2.at (0, 0) = U1.at (0, 0) * spike_out;
                            U2.at (nc2 + 1, nc1 + 1) = U1.at (nc2 + 1, nc1 + 1) * spike_out; }
    return std::array<W, 4> { U1, U2, U3, U4 };
  };

  auto call = [&] (std::array<W, 4> &U, int ilo) {
    sisal_array_t a[4] = { U[0].dope (), U[1].dope (), U[2].dope (), U[3].dope () };
    auto r = func_MAIN (a[0], a[1], a[2], a[3], nc1, nc2, ncx, ilo, gamma,
                        half, small, gm1);
    for (auto &x : a) if (x.data) free (x.data);
    return r;
  };
  auto freer = [] (FUNC_MAIN_upp_results &r) {
    sisal_array_t *v[] = { &r.rho, &r.u, &r.v, &r.e, &r.psml, &r.p, &r.c };
    for (auto *x : v) if (x->data) free (x->data);
  };

  // result planes from Method1/2 span 1-ncx .. n+ncx
  const int RW = nc1 + 2 * ncx, RH = nc2 + 2 * ncx;
  auto ridx = [&] (int j, int i) { return (size_t)(j - (1 - ncx)) * RW + (i - (1 - ncx)); };

  // ---- Method1 inverts, and honours the ilo offset ----
  for (int ilo : { 1, 2, 3 })
    {
      auto U = build (ilo, false, false, 0, 0);
      auto r = call (U, ilo);
      bool ok = r.rho.rank == 2 && (int)r.rho.dims[0] == RH
                && (int)r.rho.dims[1] == RW;
      for (int j = 1 - ncx; ok && j <= nc2 + ncx; j++)
        for (int i = 1 - ncx; i <= nc1 + ncx; i++)
          {
            int ii = i + ilo - 1;                       // the source column
            const double *R = (const double *)r.rho.data;
            const double *Uu = (const double *)r.u.data;
            const double *Ee = (const double *)r.e.data;
            double rho = R[ridx (j, i)];
            if (rho != U[0].at (j, ii)) { ok = false; break; }
            // invert: rho*u must recover the momentum, rho*e the energy
            if (fabs (rho * Uu[ridx (j, i)] - U[1].at (j, ii)) > 1e-12
                || fabs (rho * Ee[ridx (j, i)] - U[3].at (j, ii)) > 1e-12)
              { ok = false; break; }
          }
      snprintf (msg, sizeof msg,
                "Method1 ilo=%d: inverts, and reads the shifted column", ilo);
      check (msg, ok);
      freer (r);
    }

  // ---- Method2 at rest reduces to the ideal-gas EOS ----
  {
    auto U = build (1, true, false, 0, 0);
    auto r = call (U, 1);
    bool ok = true;
    const double *P = (const double *)r.p.data;
    const double *S = (const double *)r.psml.data;
    for (int j = 1 - ncx; ok && j <= nc2 + ncx; j++)
      for (int i = 1 - ncx; i <= nc1 + ncx; i++)
        {
          double rho = U[0].at (j, i), e = U[3].at (j, i) / rho;
          if (S[ridx (j, i)] != 0.0
              || fabs (P[ridx (j, i)] - gm1 * rho * e) > 1e-12)
            { ok = false; break; }
        }
    check ("Method2 at rest: no kinetic energy, so p = (gamma-1)*rho*e exactly",
           ok);
    freer (r);
  }

  // ---- Method2 floors the pressure when internal energy goes negative ----
  {
    auto U = build (1, false, true, 0, 0);
    auto r = call (U, 1);
    bool ok = true, floored = false;
    const double *P = (const double *)r.p.data;
    const double *S = (const double *)r.psml.data;
    for (int j = 1 - ncx; ok && j <= nc2 + ncx; j++)
      for (int i = 1 - ncx; i <= nc1 + ncx; i++)
        {
          if (P[ridx (j, i)] < 0.0) ok = false;
          if (P[ridx (j, i)] == S[ridx (j, i)]) floored = true;
        }
    check ("Method2 with negative internal energy: pressure never goes negative",
           ok);
    check ("...and the floor is what is returned there", floored);
    freer (r);
  }

  // ---- Method3 inverts ----
  {
    auto U = build (1, false, false, 0, 0);
    auto r = call (U, 1);
    const int CW = nc1 + 2, CH = nc2 + 2;
    bool ok = r.c.rank == 2 && (int)r.c.dims[0] == CH && (int)r.c.dims[1] == CW;
    const double *C = (const double *)r.c.data;
    const double *P = (const double *)r.p.data;
    const double *R = (const double *)r.rho.data;
    for (int j = 0; ok && j <= nc2 + 1; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        {
          double c = C[(size_t)j * CW + i];
          double want_p = c * c * R[ridx (j, i)] / gamma;
          if (fabs (want_p - P[ridx (j, i)]) > 1e-10 * std::max (1.0, want_p))
            { ok = false; break; }
        }
    check ("Method3 inverts: c*c*rho/gamma recovers the pressure", ok);
    freer (r);
  }

  // ---- Method4 sees the interior only ----
  {
    auto Uplain = build (1, false, false, 0, 0);
    auto rp = call (Uplain, 1);
    double base = rp.courmx;
    freer (rp);

    auto Uout = build (1, false, false, 0, 500.0);      // spike in ghost cells
    auto ro = call (Uout, 1);
    check ("Method4 ignores a spike planted OUTSIDE the interior",
           ro.courmx == base);
    freer (ro);

    auto Uin = build (1, false, false, 500.0, 0);       // spike inside
    auto ri = call (Uin, 1);
    check ("Method4 does see a spike planted INSIDE the interior",
           ri.courmx > base);
    freer (ri);
  }
}
#endif
#ifdef TEST_IFM_4_DV
// IFACTm_4, the radix-4 FFT butterfly pass (test/unit/IFm_4.sis).  Last of the
// three kernels PassFreq / PassGrid declare as `global` externs -- with this
// one, both of those become portable.
//
// Widest replace in the set: arm 2 updates EIGHT positions in one expression.
// ifac = 4, so jump = 3*iink and m = n/4.
//
// Reference validated against OSC 13.0.3 on every parameter set below, and
// NUMERICALLY rather than textually: sin45 = 0.7071067812 is not exactly
// representable as `real`, the same trap that made a byte-exact diff misreport
// ifm_3 as three sets mismatching when it was one ulp on one element.
static void test_ifm_4_dv (void)
{
  printf ("\n=== Group: ifm_4_dv (FFT radix-4 pass, eight-position replace) ===\n");
  struct Cfg { int n, la, inc1, inc2; };
  const Cfg cfgs[] = { { 32, 1, 2, 1 }, { 64, 2, 2, 1 }, { 32, 2, 1, 1 },
                       { 48, 1, 3, 1 }, { 64, 1, 2, 2 }, { 80, 2, 3, 1 } };
  const int NEL = 400;
  for (const Cfg &cf : cfgs)
    {
      const int m = cf.n / 4, iink = cf.inc1 * cf.la, jink = cf.inc2 * m,
                jump = 3 * iink;
      std::vector<float> a (NEL + 1), ci (NEL + 1, 0.f), trigs (NEL + 1);
      for (int i = 1; i <= NEL; i++)
        { a[i] = (float)i / 8.0f; trigs[i] = (float)i / 16.0f; }
      std::vector<float> ref = ifm4ref::kernel (m, cf.la, iink, jink, jump,
                                                cf.inc1, cf.inc2, a, ci, trigs);
      auto mk = [&] (const std::vector<float> &src) {
        sisal_array_t A = sisal_array_alloc_empty (1, 3, (uint64_t)NEL);
        A.dims[0] = NEL; A.lower_bound[0] = 1;
        for (int i = 1; i <= NEL; i++) ((float *)A.data)[i - 1] = src[i];
        return A;
      };
      sisal_array_t aa = mk (a), cc = mk (ci), tt = mk (trigs);
      sisal_array_t r = func_MAIN (m, cf.la, iink, jink, jump, cf.inc1,
                                   cf.inc2, aa, cc, tt);
      char msg[176];
      snprintf (msg, sizeof msg, "n=%-2d la=%d inc1=%d inc2=%d result is %d reals",
                cf.n, cf.la, cf.inc1, cf.inc2, NEL);
      check (msg, (int)r.size == NEL && r.rank == 1);
      bool ok = ((int)r.size == NEL);
      for (int i = 1; ok && i <= NEL; i++)
        ok = ok && (fabs ((double)((const float *)r.data)[i - 1]
                          - (double)ref[i]) < 1e-5);
      snprintf (msg, sizeof msg,
                "n=%-2d la=%d inc1=%d inc2=%d butterfly matches the reference",
                cf.n, cf.la, cf.inc1, cf.inc2);
      check (msg, ok);
    }
}
#endif
#ifdef TEST_IFM_3_DV
// IFACTm_3, the radix-3 FFT butterfly pass (test/unit/IFm_3.sis).  Second of the
// three kernels PassFreq / PassGrid declare as `global` externs.  Same skeleton
// as ifm_2etc_dv -- nested for-initial with an array carry, three-way IF
// returning (integer, integer, array_dv) -- with more arithmetic and a SIX
// position replace in arm 2:
//     c1[ja1 : ..; jb : a2-b3; jcxx : a2+b3;
//        ja1+1 : ..; jb+1 : b2+a3; jcxx+1 : a3-b2]
// ifac = 3 here, so jump = 2*iink and m = n/3.
//
// Reference checked against OSC 13.0.3 on every parameter set below before
// being trusted.  Comparison is NUMERIC, not textual: sin60 carries more digits
// than `real` holds, so OSC and the C differ by 1 ulp on the odd element.
static void test_ifm_3_dv (void)
{
  printf ("\n=== Group: ifm_3_dv (FFT radix-3 pass, six-position replace) ===\n");
  struct Cfg { int n, la, inc1, inc2; };
  const Cfg cfgs[] = { { 24, 1, 2, 1 }, { 48, 2, 2, 1 }, { 24, 2, 1, 1 },
                       { 36, 1, 3, 1 }, { 48, 1, 2, 2 }, { 60, 2, 3, 1 } };
  const int NEL = 400;
  for (const Cfg &cf : cfgs)
    {
      const int m = cf.n / 3, iink = cf.inc1 * cf.la, jink = cf.inc2 * m,
                jump = 2 * iink;
      std::vector<float> a (NEL + 1), ci (NEL + 1, 0.f), trigs (NEL + 1);
      for (int i = 1; i <= NEL; i++)
        { a[i] = (float)i / 8.0f; trigs[i] = (float)i / 16.0f; }
      std::vector<float> ref = ifm3ref::kernel (m, cf.la, iink, jink, jump,
                                                cf.inc1, cf.inc2, a, ci, trigs);
      auto mk = [&] (const std::vector<float> &src) {
        sisal_array_t A = sisal_array_alloc_empty (1, 3, (uint64_t)NEL);
        A.dims[0] = NEL; A.lower_bound[0] = 1;
        for (int i = 1; i <= NEL; i++) ((float *)A.data)[i - 1] = src[i];
        return A;
      };
      sisal_array_t aa = mk (a), cc = mk (ci), tt = mk (trigs);
      sisal_array_t r = func_MAIN (m, cf.la, iink, jink, jump, cf.inc1,
                                   cf.inc2, aa, cc, tt);
      char msg[176];
      snprintf (msg, sizeof msg, "n=%-2d la=%d inc1=%d inc2=%d result is %d reals",
                cf.n, cf.la, cf.inc1, cf.inc2, NEL);
      check (msg, (int)r.size == NEL && r.rank == 1);
      bool ok = ((int)r.size == NEL);
      for (int i = 1; ok && i <= NEL; i++)
        ok = ok && (fabs ((double)((const float *)r.data)[i - 1]
                          - (double)ref[i]) < 1e-5);
      snprintf (msg, sizeof msg,
                "n=%-2d la=%d inc1=%d inc2=%d butterfly matches the reference",
                cf.n, cf.la, cf.inc1, cf.inc2);
      check (msg, ok);
    }
}
#endif
#ifdef TEST_IFM_2ETC_DV
// IFACTm_2ETC, the radix-2 FFT butterfly pass (test/unit/IFm_2ETC.sis).  One of
// the three kernels PassFreq / PassGrid declare as `global` externs, which is
// the only reason those two cannot be promoted.
//
// Covers, in one function and nowhere else in the suite:
//   * a NESTED for-initial whose carry is an ARRAY -- outer over k carrying
//     (ia, ja, c), each arm over l carrying (ia1, ja1, c1), `value of` on the
//     array carry at both levels;
//   * MULTI-VALUE array replace, four positions in one expression:
//     c1[ja1 : v1; jbxx : v2; ja1+1 : v3; jbxx+1 : v4];
//   * a three-way IF whose result is a TUPLE of (integer, integer, array_dv);
//   * `real` (single precision) elements.
//
// The reference below is the same butterfly transcribed to C.  Index arithmetic
// this dense is where a transcription slips, so it was checked against OSC
// 13.0.3 on every parameter set here BEFORE being trusted -- and OSC's runtime
// subscript checking is what confirms these inputs stay in range, since we read
// past the end silently.  All three agree on all 400 elements, all 7 sets.
//
// `old X` in a Sisal body is the value at ITERATION ENTRY, so every read of
// old ia1 / old ja1 / old l within one body sees the same value -- hence the
// explicit *_old locals rather than updating in place.
static void test_ifm_2etc_dv (void)
{
  printf ("\n=== Group: ifm_2etc_dv (FFT radix-2 pass, nested array carries) ===\n");
  struct Cfg { int n, la, inc1, inc2; };
  const Cfg cfgs[] = { { 16, 1, 2, 1 }, { 32, 2, 2, 1 }, { 16, 2, 1, 1 },
                       { 24, 1, 3, 1 }, { 32, 1, 2, 2 }, { 40, 2, 3, 1 },
                       { 16, 4, 1, 1 } };
  const int NEL = 400;
  for (const Cfg &cf : cfgs)
    {
      const int m = cf.n / 2, iink = cf.inc1 * cf.la, jink = cf.inc2 * m,
                jump = iink;
      std::vector<float> a (NEL + 1), ci (NEL + 1, 0.f), trigs (NEL + 1);
      for (int i = 1; i <= NEL; i++)
        { a[i] = (float)i / 8.0f; trigs[i] = (float)i / 16.0f; }
      std::vector<float> ref = ifm2ref::kernel (m, cf.la, iink, jink, jump,
                                                cf.inc1, cf.inc2, a, ci, trigs);

      auto mk = [&] (const std::vector<float> &src) {
        sisal_array_t A = sisal_array_alloc_empty (1, 3, (uint64_t)NEL);
        A.dims[0] = NEL; A.lower_bound[0] = 1;
        for (int i = 1; i <= NEL; i++) ((float *)A.data)[i - 1] = src[i];
        return A;
      };
      sisal_array_t aa = mk (a), cc = mk (ci), tt = mk (trigs);
      sisal_array_t r = func_MAIN (m, cf.la, iink, jink, jump, cf.inc1,
                                   cf.inc2, aa, cc, tt);

      char msg[176];
      snprintf (msg, sizeof msg, "n=%-2d la=%d inc1=%d inc2=%d result is %d reals",
                cf.n, cf.la, cf.inc1, cf.inc2, NEL);
      check (msg, (int)r.size == NEL && r.rank == 1);
      bool ok = ((int)r.size == NEL);
      for (int i = 1; ok && i <= NEL; i++)
        ok = ok && (fabs ((double)((const float *)r.data)[i - 1]
                          - (double)ref[i]) < 1e-5);
      snprintf (msg, sizeof msg,
                "n=%-2d la=%d inc1=%d inc2=%d butterfly matches the reference",
                cf.n, cf.la, cf.inc1, cf.inc2);
      check (msg, ok);
    }
}
#endif

